mapper.select:
SELECT c.collection_id, c.member_id, c.title, c.artist_name, c.format, c.release_year, c.cover_image_url, c.linked_pairing_id, c.note, p.pairing_score, c.created_at, c.updated_at FROM collection c LEFT JOIN pairing p ON p.pairing_id = c.linked_pairing_id WHERE c.member_id = #{memberId}
AND c.format = #{format}
AND ( c.title LIKE CONCAT('%', #{keyword}, '%') OR c.artist_name LIKE CONCAT('%', #{keyword}, '%') OR c.note LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.created_at DESC, c.collection_id DESC

SELECT 
FROM collection
WHERE collection_id = #{collectionId}
  AND member_id = #{memberId}

